def build_system(persona, language='ko', max_words=None):
    parts = [f'당신은 {persona}입니다.']
    if language != 'ko':
        parts.append('영어로 답하세요.')
    if max_words:
        parts.append(f'{max_words}단어 이내로 답하세요.')
    return ' '.join(parts)

